-- Compare v0.1. Dedicated database only; no DROP or existing-business writes.
CREATE DATABASE IF NOT EXISTS rentwise_content_v04 CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE rentwise_content_v04;
CREATE TABLE IF NOT EXISTS city(id BIGINT PRIMARY KEY,slug VARCHAR(64) NOT NULL UNIQUE,name VARCHAR(80) NOT NULL);
CREATE TABLE IF NOT EXISTS metric(id BIGINT PRIMARY KEY,code VARCHAR(64) NOT NULL UNIQUE,name VARCHAR(120) NOT NULL,dimension VARCHAR(40) NOT NULL,kind VARCHAR(20) NOT NULL,INDEX idx_metric_dimension(dimension));
CREATE TABLE IF NOT EXISTS source(id BIGINT PRIMARY KEY,title VARCHAR(255) NOT NULL,url VARCHAR(1000) NOT NULL,checked_at DATE NOT NULL);
CREATE TABLE IF NOT EXISTS city_metric_value(id BIGINT PRIMARY KEY,city_id BIGINT NOT NULL,metric_id BIGINT NOT NULL,source_id BIGINT NOT NULL,text_value TEXT,numeric_value DECIMAL(18,4),period VARCHAR(80) NOT NULL,unit VARCHAR(80) NOT NULL,scope VARCHAR(255) NOT NULL,method VARCHAR(255) NOT NULL,UNIQUE KEY uq_city_metric(city_id,metric_id),FOREIGN KEY(city_id) REFERENCES city(id),FOREIGN KEY(metric_id) REFERENCES metric(id),FOREIGN KEY(source_id) REFERENCES source(id),INDEX idx_value_source(source_id));
